/* From Uiverse.io by TemRevil  - Tags: simple, animation, action, card */
.__UIV_SCOPE__ .card {
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 190px;
  height: 254px;
  background: #023047;
  color: white;
  font-size: 32px;
  font-weight: 700;
  border-radius: 10px;
  cursor: pointer;
  transition: 0.1s 0s linear;
  position: relative;
  overflow: hidden;
}
.__UIV_SCOPE__ .card:active {
  scale: 0.95;
}
.__UIV_SCOPE__ .card::after {
  content: "";
  width: 500px;
  height: 500px;
  border-radius: 50%;
  background-color: #fb8500;
  position: absolute;
  right: 250px;
  transition: right 0.4s 0s linear;
  z-index: 1;
}
.__UIV_SCOPE__ .card:hover::after {
  right: -160px;
}
.__UIV_SCOPE__ .card:hover {
  color: #023047;
}
.__UIV_SCOPE__ .card p {
  position: absolute;
  z-index: 10;
}
